@using sv_2c0b73230e414bd89d75e2d2bb5b0ed9.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white me-2" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.SelectedWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString() ?? "";
        var name = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;
        WarehouseState.SetWarehouse(id, name);
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

