                        <h2>@AlertService.LowStockCount</h2>
                        <p class="mb-0">Low Stock Items</p>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <p class="text-muted">
                    Monitoring inventory levels for <strong>@WarehouseState.SelectedWarehouseName</strong>.
                    Alert data refreshes every 10 seconds.
                </p>
                @if (AlertService.LowStockCount > 5)
                {
                    <div class="alert alert-danger">
                        ⚠️ Critical: @AlertService.LowStockCount items are below minimum stock levels!
                    </div>
                }
                else if (AlertService.LowStockCount > 0)
                {
                    <div class="alert alert-warning">
                        ⚡ @AlertService.LowStockCount item(s) below minimum levels. Review recommended.
                    </div>
                }
                else
                {
                    <div class="alert alert-success">
                        ✅ All inventory levels are healthy.
                    </div>
                }
            </div>
        </div>
    </div>
</div>

