@using sv_2c0b73230e414bd89d75e2d2bb5b0ed9.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white me-2" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.SelectedWarehouseId" @onchange="OnWarehouseChanged">
