@page "/dashboard"
@using sv_2c0b73230e414bd89d75e2d2bb5b0ed9.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">@WarehouseState.SelectedWarehouseName</h5>
    </div>
    <div class="card-body">
        <div class="row">
            <div class="col-md-4">
                <div class="card text-bg-@(AlertService.LowStockCount > 5 ? "danger" : AlertService.LowStockCount > 0 ? "warning" : "success")">
                    <div class="card-body text-center">
                        <h2>@AlertService.LowStockCount</h2>
                        <p class="mb-0">Low Stock Items</p>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <p class="text-muted">
                    Monitoring inventory levels for <strong>@WarehouseState.SelectedWarehouseName</strong>.
                    Alert data refreshes every 10 seconds.
                </p>
                @if (AlertService.LowStockCount > 5)
                {
                    <div class="alert alert-danger">
                        ⚠️ Critical: @AlertService.LowStockCount items are below minimum stock levels!
                    </div>
                }
                else if (AlertService.LowStockCount > 0)
                {
                    <div class="alert alert-warning">
                        ⚡ @AlertService.LowStockCount item(s) below minimum levels. Review recommended.
                    </div>
                }
                else
                {
                    <div class="alert alert-success">
                        ✅ All inventory levels are healthy.
                    </div>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

